head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > P > applyFormat]<br/>입력값 편집시에도 displayFormat 속성에 설정된 포맷을 적용할지 설정합니다.",
    "validation" : [
        "dataType 속성값이 text, date, time 이면 항상 'display' 로 동작합니다.",
        "미설정 시 입력이 완료된 후 포커스가 해제되면 displayFormat 속성의 포맷이 적용됩니다.",
        "'display' (default) 설정 시 입력이 완료된 후 포커스가 해제되면 displayFormat 속성의 포맷이 적용됩니다.",
        "'all' 설정 시 입력값을 편집하는 중에도 displayFormat 속성의 포맷이 적용됩니다.",
        "일반적으로 천단위 ',' 를 입력중에도 표시하고자 할때 주로 사용합니다.",
        "SearchBox 의 입력값은 포맷이 제거된 실제 입력값이 저장됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text_edit = function(target) {
    let rtn = '';
    let inputElem = target.render.querySelector("input");

    if (inputElem) {
        rtn = inputElem.value;
        wf_body_bottom.getObj("scwin").setReturnValue("text(edit) : " + rtn);
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("input element not found");
    }
}



scwin.get_text_display = function(target) {
    let rtn = '';
    let inputElem = target.render.querySelector("input");

    if (inputElem) {
        rtn = inputElem.value;
        wf_body_bottom.getObj("scwin").setReturnValue("text(display) : " + rtn);
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("input element not found");
    }
}



scwin.get_value = function(target) {
    wf_body_bottom.getObj("scwin").setReturnValue("getValue : " + target.getValue());
}



// target1 : dataType=number, displayFormat=#,###, applyFormat=미설정
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("123456789");
    target1.focus();
};

scwin.btn_getText1_onclick = function (e) {
    scwin.get_text_display(target1);
}

scwin.btn_getValue1_onclick = function (e) {
    scwin.get_value(target1);
}

// target2 : dataType=number, displayFormat=#,###, applyFormat=all
scwin.btn_setValue2_onclick = function (e) {
    target2.setValue("123456789");
    target2.focus();
};

scwin.btn_getText2_onclick = function (e) {
    scwin.get_text_display(target2);
}

scwin.btn_getValue2_onclick = function (e) {
    scwin.get_value(target2);
}

// target3 : dataType=number, displayFormat=#,###, applyFormat=display
scwin.btn_setValue3_onclick = function (e) {
    target3.setValue("123456789");
    target3.focus();
};

scwin.btn_getText3_onclick = function (e) {
    scwin.get_text_display(target3);
};

scwin.btn_getValue3_onclick = function (e) {
    scwin.get_value(target3);
}

// target4 : dataType=text, displayFormat=#:##-##, applyFormat=all -> text 는 항상 display 로 동작
scwin.btn_setValue4_onclick = function (e) {
    target4.setValue("langkoKR");
    target4.focus();
};

scwin.btn_getText4_onclick = function (e) {
    scwin.get_text_display(target4);
};

scwin.btn_getValue4_onclick = function (e) {
    scwin.get_value(target4);
}

// target5 : dataType=date, displayFormat=dd/MM/yyyy, applyFormat=all -> date 는 항상 display 로 동작
scwin.btn_setValue5_onclick = function (e) {
    target5.setValue("20080501");
    target5.focus();
};

scwin.btn_getText5_onclick = function (e) {
    scwin.get_text_display(target5);
};

scwin.btn_getValue5_onclick = function (e) {
    scwin.get_value(target5);
}

// target6 : dataType=time, displayFormat=HH:mm:ss, applyFormat=all -> time 은 항상 display 로 동작
scwin.btn_setValue6_onclick = function (e) {
    target6.setValue("121521");
    target6.focus();
};

scwin.btn_getText6_onclick = function (e) {
    scwin.get_text_display(target6);
};

scwin.btn_getValue6_onclick = function (e) {
    scwin.get_value(target6);
}



scwin.btn_setAll_onclick = function (e) {
    for (var i = 1; i < 7; i ++)
        eval("scwin.btn_setValue"+i+"_onclick()");
}

scwin.btn_getAll_onclick = function (e) {
    for (var i = 1; i < 7; i ++)
        eval("scwin.btn_getText"+i+"_onclick()");
};

scwin.btn_getAllValue_onclick = function (e) {
    for (var i = 1; i < 7; i ++)
        eval("scwin.btn_getValue"+i+"_onclick()");
};



scwin.target_onfocus = function (e) {
    let inputElem = e.target.tagName === "INPUT" ? e.target : e.target.querySelector("input");
    let rtn = inputElem ? inputElem.value : '';
    wf_body_bottom.getObj("scwin").setReturnValue("text(edit) : " + rtn);
};
